def paired_rows(names, scores):
    return list(zip(names, scores, strict=True))

assert paired_rows(['Ada', 'Bo'], [80, 90]) == [('Ada', 80), ('Bo', 90)]
for names, scores in ((['Ada', 'Bo'], [80]), (['Ada'], [80, 90])):
    try:
        paired_rows(names, scores)
    except ValueError:
        pass
    else:
        raise AssertionError('mismatch was accepted')
print('strict pairing checked')
